-- ── story 4-3a: the client allocation policy ─────────────────────────────
-- Generated by drizzle-kit (the four column statements) and hand-amended
-- around the generated part: the fail-fast guard, the six CHECKs and the
-- post-migration probe (drizzle-kit is blind to CHECKs; `bun run db:generate`
-- afterwards reports "No schema changes").
--
-- `clients` (one row per brand — small):
--   * `allocation_rule text NOT NULL DEFAULT 'fefo'` — `fefo` | `fifo`
--     (`ALLOCATION_RULES`, src/shared/primitives/batch-allocation.ts,
--     re-exported by src/modules/clients/clients.schema.ts). A constant
--     default, so the ADD COLUMN is metadata-only; every existing client reads
--     `fefo` — a DELIBERATE behaviour change at deploy (decision 3, A4: batch
--     stock is drawn warehouse-wide earliest-expiry first).
--   * `min_outbound_shelf_life_days integer NULL` — 1..3650 IST days, NULL for
--     none. No pairing with `expiry_required` (decision 2).
--   Both CHECKs are added VALID: the scan over one row per brand is trivial.
--
-- `picklist_lines` (large — every wave writes it):
--   * `allocation_rule text NULL` and `min_outbound_shelf_life_days integer
--     NULL` — the policy a line was planned under, FROZEN (decision 7). No
--     default: an existing line stays NULL, the legacy arm (drawn as `fefo`
--     with no minimum: the named batch first, then in-bin FEFO — undated lots
--     now tie-break on first receipt, not batch id; A2, A4).
--   * the three CHECKs (range, vocabulary, pairing — A18) are NOT VALID (guide
--     §3): a VALID add would scan the table under the ADD COLUMN's ACCESS
--     EXCLUSIVE lock. NOT VALID still enforces every insert and update from
--     here on, and every existing row is NULL/NULL by construction, which all
--     three admit. No VALIDATE here (the migrator runs the pending set in one
--     transaction) — a PENDING (deploy) entry instead.
--   `IS NULL OR` comes first on every nullable arm (guide §3).
--
-- No backfill and no index.
--
-- Lock cost: each ALTER TABLE takes a brief ACCESS EXCLUSIVE lock (no rewrite,
-- no scan on `picklist_lines`). The deploy migrator sets `lock_timeout` on its
-- connection (MIGRATE_LOCK_TIMEOUT_MS, default 5 s, `migrate-deploy.ts`): while
-- one ALTER waits, later traffic on that table queues behind it; on a timeout
-- the migrator's one transaction rolls back whole and the remedy is to re-run
-- the deploy (at a quieter moment if it recurs — DEPLOY.md §5).
--
-- Rolling deploy (A18): an old api task that picks a new `fifo` line ignores
-- the columns and draws in-bin FEFO — accepted for one deploy window; the draw
-- is still rotation-safe.

-- ── 0. fail-fast: already applied ────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'clients' AND column_name = 'allocation_rule'
	) THEN
		RAISE EXCEPTION 'migration 0094: clients.allocation_rule already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "allocation_rule" text DEFAULT 'fefo' NOT NULL;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "min_outbound_shelf_life_days" integer;--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD COLUMN "allocation_rule" text;--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD COLUMN "min_outbound_shelf_life_days" integer;--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ────────────────────────
-- Mirrored by ALLOCATION_RULES / MIN_OUTBOUND_SHELF_LIFE_DAYS_MIN/MAX, pinned
-- against these definitions by test/allocation-rules.spec.ts.
ALTER TABLE "clients" ADD CONSTRAINT "clients_allocation_rule_check" CHECK (
	"allocation_rule" IN ('fefo','fifo')
);--> statement-breakpoint
ALTER TABLE "clients" ADD CONSTRAINT "clients_min_outbound_shelf_life_range" CHECK (
	"min_outbound_shelf_life_days" IS NULL OR "min_outbound_shelf_life_days" BETWEEN 1 AND 3650
);--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_allocation_rule_check" CHECK (
	"allocation_rule" IS NULL OR "allocation_rule" IN ('fefo','fifo')
) NOT VALID;--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_min_outbound_shelf_life_range" CHECK (
	"min_outbound_shelf_life_days" IS NULL OR "min_outbound_shelf_life_days" BETWEEN 1 AND 3650
) NOT VALID;--> statement-breakpoint
-- A line is legacy exactly when `allocation_rule IS NULL`: a minimum never
-- appears without the rule it was planned with (A18).
ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_allocation_pairing" CHECK (
	"allocation_rule" IS NOT NULL OR "min_outbound_shelf_life_days" IS NULL
) NOT VALID;--> statement-breakpoint
-- ── the post-migration assertion (the 0088 model) ─────────────────────────
-- Made-up uuids. (a) The three picklist_lines CHECKs are NOT VALID, the two
-- clients CHECKs VALID. (b) Every existing client reads fefo/NULL. (c) The
-- accepted shapes (a client and full valid picklist_lines rows) are inserted
-- and rolled back by a sentinel exception, so a CHECK that refused everything
-- fails the migration. (d) Each refused shape runs in its own subtransaction
-- and must be refused BY ITS NAMED CONSTRAINT.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	n int;
BEGIN
	-- (a)
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE conrelid = 'public.picklist_lines'::regclass
	   AND conname IN ('picklist_lines_allocation_rule_check', 'picklist_lines_min_outbound_shelf_life_range', 'picklist_lines_allocation_pairing')
	   AND contype = 'c'
	   AND NOT convalidated;
	IF n <> 3 THEN
		RAISE EXCEPTION 'migration 0094: expected the three picklist_lines CHECKs present and NOT VALID, found % so.', n;
	END IF;
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE conrelid = 'public.clients'::regclass
	   AND conname IN ('clients_allocation_rule_check', 'clients_min_outbound_shelf_life_range')
	   AND contype = 'c'
	   AND convalidated;
	IF n <> 2 THEN
		RAISE EXCEPTION 'migration 0094: expected the two clients CHECKs present and VALID, found % so.', n;
	END IF;
	-- (b)
	SELECT count(*) INTO n FROM "clients"
	 WHERE "allocation_rule" IS DISTINCT FROM 'fefo' OR "min_outbound_shelf_life_days" IS NOT NULL;
	IF n <> 0 THEN
		RAISE EXCEPTION 'migration 0094: % existing client(s) do not read fefo/NULL.', n;
	END IF;
	-- (c)
	BEGIN
		INSERT INTO "clients" ("id","tenant_id","code","name") VALUES (c, t, 'PROBE-0094', 'probe');
		IF (SELECT "allocation_rule" FROM "clients" WHERE "id" = c) IS DISTINCT FROM 'fefo' THEN
			RAISE EXCEPTION 'migration 0094: a client inserted without a rule did not read fefo.';
		END IF;
		INSERT INTO "clients" ("id","tenant_id","code","name","allocation_rule","min_outbound_shelf_life_days")
		VALUES
			(gen_random_uuid(), t, 'PROBE-0094-A', 'probe', 'fifo', 1),
			(gen_random_uuid(), t, 'PROBE-0094-B', 'probe', 'fefo', 3650),
			(gen_random_uuid(), t, 'PROBE-0094-C', 'probe', 'fifo', NULL);
		INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","min_outbound_shelf_life_days")
		VALUES
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, NULL, NULL),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', NULL),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fifo', 1),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', 3650);
		RAISE EXCEPTION USING ERRCODE = 'P0094', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0094: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0094' THEN
			NULL;
	END;
	-- (d)
	FOREACH probe IN ARRAY ARRAY[
		'client lifo', 'client null', 'client min 0', 'client min 3651',
		'line lifo', 'line min 0', 'line min 3651', 'line pairing'
	] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe = 'client lifo' THEN 'clients_allocation_rule_check'
			WHEN probe = 'client null' THEN 'not-null'
			WHEN probe IN ('client min 0', 'client min 3651') THEN 'clients_min_outbound_shelf_life_range'
			WHEN probe = 'line lifo' THEN 'picklist_lines_allocation_rule_check'
			WHEN probe IN ('line min 0', 'line min 3651') THEN 'picklist_lines_min_outbound_shelf_life_range'
			ELSE 'picklist_lines_allocation_pairing'
		END;
		BEGIN
			CASE probe
				WHEN 'client lifo' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","allocation_rule") VALUES (gen_random_uuid(), t, 'PROBE-0094-D', 'probe', 'lifo');
				WHEN 'client null' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","allocation_rule") VALUES (gen_random_uuid(), t, 'PROBE-0094-D', 'probe', NULL);
				WHEN 'client min 0' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","min_outbound_shelf_life_days") VALUES (gen_random_uuid(), t, 'PROBE-0094-D', 'probe', 0);
				WHEN 'client min 3651' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","min_outbound_shelf_life_days") VALUES (gen_random_uuid(), t, 'PROBE-0094-D', 'probe', 3651);
				WHEN 'line lifo' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'lifo');
				WHEN 'line min 0' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","min_outbound_shelf_life_days")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', 0);
				WHEN 'line min 3651' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","min_outbound_shelf_life_days")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', 3651);
				WHEN 'line pairing' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","min_outbound_shelf_life_days")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, NULL, 90);
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN not_null_violation THEN
				refused_by := 'not-null';
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0094: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "clients" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "picklist_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0094: a probe row survived.';
	END IF;
END $$;
